class Money:
    def __init__(self, cents):
        self.cents = cents

    def __add__(self, o):
        if isinstance(o, Money):
            return Money(self.cents + o.cents)
        return NotImplemented

    def __radd__(self, o):
        if o == 0 or isinstance(o, Money):
            return self.__add__(o if isinstance(o, Money) else Money(0))
        return NotImplemented

    def __eq__(self, o):
        return isinstance(o, Money) and self.cents == o.cents

    def __hash__(self):
        return hash(self.cents)

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        return f'${self.cents / 100:,.2f}'

    def split(self, n):
        if n <= 0:
            raise ValueError('cannot split into %d parts' % n)
        share, remainder = divmod(self.cents, n)
        return [Money(share + (1 if i < remainder else 0)) for i in range(n)]
